(function(){
  function cls(n){ return Java.loadClass(n); }
  var BR = cls("net.minecraft.core.registries.BuiltInRegistries");
  var State = cls("com.merlinkitsune.astral_dice.shop.ChipShopState");
  var Opener = cls("com.merlinkitsune.astral_dice.shop.ChipShopOpener");
  var Econ = cls("com.merlinkitsune.starengine.economy.StarEngineEconomy");
  var player = AutoJS.players()[0];
  var out = {};
  function chipCount() {
    var n = 0, inv = player.getInventory();
    for (var i = 0; i < Number(inv.getContainerSize()); i++) {
      var st = inv.getItem(i);
      if (st != null && !st.isEmpty()) {
        var p = String(BR.ITEM.getKey(st.getItem()).getPath());
        if (p.indexOf("chip") >= 0) { n += st.getCount(); }
      }
    }
    return n;
  }
  out.econAvailable = Econ.isAvailable();
  var bal0 = Number(Econ.getBalance(player));
  out.bal0 = bal0;
  player.closeContainer();
  State.store(player, State.EMPTY);
  Opener.open(player);
  var m = player.containerMenu;
  out.menuIsShop = String(m).indexOf("ChipShopMenu") >= 0;
  if (!out.menuIsShop) { out.abort = true; Econ.setBalance(player, bal0); return out; }
  out.abort = false;
  out.priceBefore = Number(m.price());
  var chipsBefore = chipCount();
  Econ.setBalance(player, 0);
  m.handleBuy(player, 0);
  out.denyVisibleServer = Number(m.denyReason());
  out.purchasedAfterDeny = Number(State.get(player).purchasedCount());
  out.balanceAfterDeny = Number(Econ.getBalance(player));
  out.cooldownAfterDeny = Number(State.get(player).cooldownUntil());
  out.chipsAfterDeny = chipCount() - chipsBefore;
  out.menuStillShopAfterDeny = String(player.containerMenu).indexOf("ChipShopMenu") >= 0;
  Econ.setBalance(player, 100);
  if (!out.menuStillShopAfterDeny) { Opener.open(player); m = player.containerMenu; }
  out.priceAtBuy = Number(m.price());
  m.handleBuy(player, 0);
  var st = State.get(player);
  out.purchasedAfterBuy = Number(st.purchasedCount());
  out.balanceAfterBuy = Number(Econ.getBalance(player));
  out.spent = 100 - out.balanceAfterBuy;
  out.chipsGained = chipCount() - chipsBefore;
  out.cooldownUntil = Number(st.cooldownUntil());
  out.cooldownSet = Number(st.cooldownUntil()) > 0;
  out.menuClosedAfterBuy = String(player.containerMenu).indexOf("ChipShopMenu") < 0;
  State.store(player, State.EMPTY);
  Econ.setBalance(player, bal0);
  AutoJS.command("/clear @a");
  out.balanceRestored = Number(Econ.getBalance(player)) === bal0;
  out.chipsAfterClean = chipCount();
  return out;
})()
